EXECUTE IMMEDIATE $$WITH wt AS ( SELECT column1 AS plat, column2 AS w_ja4, column3 AS w_scr, column4 AS w_dp, column5 AS w_ua, column6 AS w_gl FROM VALUES ('Windows',0.10,0.15,0.30,0.15,0.30), ('macOS',0.15,0.35,0.15,0.20,0.15), ('Linux',0.25,0.20,0.25,0.15,0.15), ('ChromeOS',0.15,0.20,0.25,0.15,0.25), ('Android',0.05,0.30,0.05,0.20,0.40), ('iOS',0.15,0.40,0.05,0.30,0.10) ), sess_raw AS ( SELECT session, di_dictionary_num_matched_at_session_created AS d, di_highest_signature_at_session_created AS h, latest_risk_band AS risk, (sessions_verified > 0) AS verified, (sessions_verify_attempted > 0) AS va, (was_challenged > 0) AS ch, (sessions_solved > 0) AS solved FROM ARK_PROD.STARFLEET.PROD_INT_SESSION_SUMMARY WHERE public_key = 'A207F8A1-ED09-4325-ACE6-C8E26A458FBA' AND session_last_timestamp >= '2026-11-20 12:00:00' AND session_ts >= '2026-11-20 12:00:00' AND session_ts < '2026-11-20 14:00:00' ), wl_raw AS ( SELECT di_highest_signature_at_session_created AS h, COUNT(*) AS n FROM ARK_PROD.STARFLEET.PROD_INT_SESSION_SUMMARY WHERE public_key IN ('A207F8A1-ED09-4325-ACE6-C8E26A458FBA','955D26AF-E956-4106-A4EF-2F63304776D9') AND session_last_timestamp >= '2026-11-13 00:00:00' AND session_last_timestamp < '2026-11-20 06:00:00' AND session_ts >= '2026-11-13 00:00:00' AND session_ts < '2026-11-20 00:00:00' AND di_dictionary_num_matched_at_session_created = 63 GROUP BY 1 ), p AS ( SELECT h, SPLIT_PART(SPLIT_PART(h,'||',1),'::',1) AS osf, SPLIT_PART(SPLIT_PART(h,'||',1),'::',2) AS osv, SPLIT_PART(h,'||',2) AS ja4, SPLIT_PART(h,'||',3) AS scr, SPLIT_PART(h,'||',4) AS dp, SPLIT_PART(h,'||',5) AS ua, SPLIT_PART(h,'||',6) AS gl FROM (SELECT h FROM sess_raw UNION SELECT h FROM wl_raw) ), p2 AS ( SELECT p.*, LEFT(ja4,1) AS tr, CASE WHEN ua RLIKE '.*Edg(e|A|iOS)?/[0-9].*' THEN 'Edge' WHEN ua RLIKE '.*(OPR|OPT)/[0-9].*' THEN 'Opera' WHEN ua RLIKE '.*SamsungBrowser/[0-9].*' THEN 'Samsung' WHEN ua RLIKE '.*(Firefox|FxiOS)/[0-9].*' THEN 'Firefox' WHEN ua RLIKE '.*(Chrome|CriOS)/[0-9].*' THEN 'Chrome' WHEN ua RLIKE '.*Version/[0-9.]+ (Mobile/[^ ]+ )?Safari/.*' THEN 'Safari' END AS bfam, COALESCE(TRY_TO_NUMBER(SPLIT_PART(osv,'.',1)),0)*1000000 + COALESCE(TRY_TO_NUMBER(SPLIT_PART(osv,'.',2)),0)*1000 + COALESCE(TRY_TO_NUMBER(SPLIT_PART(osv,'.',3)),0) AS osv_num, CASE osf WHEN 'Windows' THEN 'Windows' WHEN 'OS X' THEN 'macOS' WHEN 'Chrome OS' THEN 'ChromeOS' WHEN 'Android' THEN 'Android' WHEN 'iOS' THEN 'iOS' WHEN 'iPadOS' THEN 'iOS' ELSE 'Linux' END AS plat, osf IN ('iOS','iPadOS','Android') AS mobile, (osf = 'Windows' AND gl ILIKE '%Basic Render Driver%') AS basic, (gl ILIKE '%SwiftShader%' OR gl ILIKE '%llvmpipe%' OR gl ILIKE '%VirtualBox%' OR gl ILIKE '%VMware%') AS soft, NOT (soft OR gl ILIKE '%Basic Render Driver%') AS hw_gl, CASE WHEN soft THEN 'Other' WHEN gl ILIKE '%Basic Render Driver%' THEN IFF(osf = 'Windows','Windows RD/VM','Other') WHEN osf IN ('Windows','OS X','Chrome OS') THEN 'Desktop' WHEN osf IN ('iOS','iPadOS','Android') THEN 'Mobile' WHEN osf IN ('GNU/Linux','Ubuntu') THEN 'Linux' ELSE 'Other' END AS pg, CASE WHEN osf IN ('iOS','iPadOS') THEN 'iOS+iPadOS' WHEN osf IN ('GNU/Linux','Ubuntu') THEN 'Linux' WHEN osf IN ('Android','Windows','OS X','Chrome OS') THEN osf END AS line, SPLIT_PART(dp,'::',1)||'::'||SPLIT_PART(dp,'::',4)||'::'||SPLIT_PART(dp,'::',5)||'::'||SPLIT_PART(dp,'::',10) ||'::'||SPLIT_PART(dp,'::',11) AS dpc, IFF(SPLIT_PART(scr,'::',2) RLIKE '[0-9]+,[0-9]+', SPLIT_PART(scr,'::',2), NULL) AS spv FROM p ), f AS ( SELECT p2.*, bfam || '/' || CASE bfam WHEN 'Edge' THEN REGEXP_SUBSTR(ua,'Edg[A-Za-z]*/([0-9]+)',1,1,'e',1) WHEN 'Opera' THEN REGEXP_SUBSTR(ua,'OP[RT]/([0-9]+)',1,1,'e',1) WHEN 'Samsung' THEN REGEXP_SUBSTR(ua,'SamsungBrowser/([0-9]+)',1,1,'e',1) WHEN 'Firefox' THEN REGEXP_SUBSTR(ua,'(Firefox|FxiOS)/([0-9]+)',1,1,'e',2) WHEN 'Chrome' THEN REGEXP_SUBSTR(ua,'(Chrome|CriOS)/([0-9]+)',1,1,'e',2) WHEN 'Safari' THEN REGEXP_SUBSTR(ua,'Version/([0-9]+)',1,1,'e',1) END AS ua_bm, HASH(ja4) AS hj, HASH(scr) AS hs, HASH(dp) AS hd, HASH(ua) AS hu, HASH(gl) AS hg, HASH(ua_bm) AS hub, HASH(COALESCE(ua_bm, ua)) AS huc, HASH(dpc) AS hdc, HASH(spv) AS hsp, (ja4 <> '') AS ja4_ok, (spv IS NOT NULL) AS sp_ok, (ua <> '') AS ua_ok, (ua_bm IS NOT NULL) AS ub_ok, (gl <> '') AS gl_ok, (ua_bm IS NOT NULL OR ua <> '') AS uc_ok, (osv <> '') AS osv_ok FROM p2 ), k AS ( SELECT f.*, ARRAY_CONSTRUCT(HASH(0,osf,hs), HASH(1,hs), HASH(2,osf,hd), HASH(3,osf,hu), HASH(4,osf,hg), HASH(5,osf,osv), HASH(6,osf,hu,hd), HASH(7,osf,hs,hd), HASH(8,osf,hs,hg), HASH(9,pg,hs), HASH(10,pg,hd), HASH(11,pg,hu), HASH(12,pg,hg), HASH(13,pg,huc), HASH(14,pg,hu,hd), HASH(15,pg,hs,hd), HASH(16,pg,hs,hg), HASH(17,pg,huc,hdc), HASH(18,pg,hs,hdc), HASH(19,line,osv), HASH(20,pg,hsp), HASH(21,hsp), HASH(22,pg,hsp,hd), HASH(23,pg,hsp,hg), HASH(24,pg,hsp,hdc)) AS ks FROM f ), wl AS (SELECT k.*, r.n AS wn FROM k JOIN wl_raw r ON r.h = k.h), pgt AS (SELECT pg, SUM(wn) AS pgn FROM wl GROUP BY pg), jf AS (SELECT DISTINCT hj, bfam FROM wl WHERE bfam IS NOT NULL), st AS ( SELECT k.*, (jf.hj IS NOT NULL) AS ja4_fam_ok, IFF(basic, w.w_ja4/0.70, w.w_ja4) AS w_ja4, IFF(basic, w.w_scr/0.70, w.w_scr) AS w_scr, IFF(basic, w.w_dp/0.70, w.w_dp) AS w_dp, IFF(basic, w.w_ua/0.70, w.w_ua) AS w_ua, IFF(basic, 0, w.w_gl) AS w_gl FROM k JOIN wt w ON w.plat = k.plat LEFT JOIN jf ON jf.hj = k.hj AND jf.bfam = k.bfam WHERE k.h IN (SELECT h FROM sess_raw) ), bm AS ( SELECT s.h, s.w_ja4, s.w_scr, s.w_dp, s.w_ua, s.w_gl, IFF(s.hj = c.hj, 2, IFF(s.tr <> c.tr AND s.bfam = c.bfam AND s.ja4_fam_ok, 1, 0)) AS jc, IFF(s.hu = c.hu, 2, IFF(s.hub = c.hub, 1, 0)) AS uc, IFF(s.hs = c.hs, 1, 0) AS sv, IFF(s.hsp = c.hsp, 1, 0) AS pv, IFF(s.hd = c.hd, 1, 0) AS dv, IFF(s.hg = c.hg, 1, 0) AS gv, IFF(s.ja4_ok, jc, 0) AS jg, CASE WHEN uc = 2 AND s.ua_ok THEN 2 WHEN uc >= 1 AND s.ub_ok THEN 1 ELSE 0 END AS ug, IFF(s.sp_ok, pv, 0) AS pg2, IFF(s.gl_ok, gv, 0) AS gg FROM st s JOIN wl c ON c.osf = s.osf ), best AS ( SELECT h, MAX(ROUND(10000 * (w_ja4 * DECODE(jc, 2, 1, 1, 2/3, 0) + w_scr * sv + w_dp * dv + w_ua * DECODE(uc, 2, 1, 1, 0.5, 0) + w_gl * gv)) * 100 + jc + 3 * uc + 9 * sv + 18 * dv + 36 * gv) AS pk_v2, MAX(ROUND(10000 * (w_ja4 * DECODE(jg, 2, 1, 1, 2/3, 0) + w_scr * pg2 + w_dp * dv + w_ua * DECODE(ug, 2, 1, 1, 0.5, 0) + w_gl * gg)) * 100 + jg + 3 * ug + 9 * pg2 + 18 * dv + 36 * gg) AS pk_s3 FROM bm GROUP BY h ), ref AS (SELECT x.value::NUMBER AS kk, SUM(wl.wn) AS cnt FROM wl, LATERAL FLATTEN(wl.ks) x GROUP BY 1), seen AS ( SELECT q.h, ARRAY_AGG(r.kk IS NOT NULL) WITHIN GROUP (ORDER BY q.i) AS z, ARRAY_AGG(COALESCE(r.cnt, 0)) WITHIN GROUP (ORDER BY q.i) AS zc FROM (SELECT s.h, x.index AS i, x.value::NUMBER AS kk FROM st s, LATERAL FLATTEN(s.ks) x) q LEFT JOIN ref r ON r.kk = q.kk GROUP BY q.h ), omx AS (SELECT osf, MAX(osv_num) AS mx FROM wl GROUP BY osf), c AS ( SELECT s.h, s.osf, s.osv, s.pg, s.line, s.mobile, s.basic, s.ua_bm, s.ua_ok, s.ub_ok, (s.pg = 'Mobile') AS mob2, (s.osf IN ('','--') OR s.dp = '') AS no_score, COALESCE(b.pk_v2, 0) AS pk, FLOOR(pk / 100) / 10000 AS score, MOD(pk, 100) AS code, COALESCE(b.pk_s3, 0) AS pk3, FLOOR(pk3 / 100) / 10000 AS score3, MOD(pk3, 100) AS code3, CASE WHEN no_score THEN 'no score' WHEN score >= 0.85 THEN IFF(s.basic,'B','A') WHEN score >= 0.65 THEN 'B' WHEN score >= 0.40 THEN 'C' ELSE 'D' END AS sb, CASE WHEN no_score THEN 'no score' WHEN score3 >= 0.85 THEN IFF(s.basic,'B','A') WHEN score3 >= 0.65 THEN 'B' WHEN score3 >= 0.40 THEN 'C' ELSE 'D' END AS sb3, z[3]::BOOLEAN AND z[2]::BOOLEAN AND NOT z[6]::BOOLEAN AS f_ua_dp, z[0]::BOOLEAN AND z[2]::BOOLEAN AND NOT z[7]::BOOLEAN AS f_scr_dp, s.hw_gl AND z[0]::BOOLEAN AND z[4]::BOOLEAN AND NOT z[8]::BOOLEAN AS f_scr_gl, z[1]::BOOLEAN AND NOT z[0]::BOOLEAN AS f_scr_os, NOT z[5]::BOOLEAN AND NOT (s.osv_num > COALESCE(o.mx,-1)) AS f_osv, NOT z[2]::BOOLEAN AS f_dp_new, NOT z[0]::BOOLEAN AND NOT s.mobile AS w_scr0, NOT z[10]::BOOLEAN AS p_dp_new, (z[9]::BOOLEAN AND s.sp_ok) AS s_scr, z[10]::BOOLEAN AS s_dp, (z[13]::BOOLEAN AND s.uc_ok) AS s_uac, (z[11]::BOOLEAN AND s.ua_ok) AS s_ua, (z[12]::BOOLEAN AND s.gl_ok) AS s_gl, (z[20]::BOOLEAN AND s.sp_ok) AS s_sp, s_uac AND s_dp AND NOT z[17]::BOOLEAN AS g_ua_dp, s_sp AND s_dp AND NOT z[24]::BOOLEAN AS h_scr_dp, s.hw_gl AND s_sp AND s_gl AND NOT z[23]::BOOLEAN AS h_scr_gl, z[21]::BOOLEAN AND s.sp_ok AND NOT z[20]::BOOLEAN AS h_scr_pg, NOT s_sp AND s.pg <> 'Mobile' AS h_w_scr, s_uac AND s_dp AND NOT g_ua_dp AND s_ua AND NOT z[14]::BOOLEAN AS x_ua_dp, s_sp AND s_dp AND NOT h_scr_dp AND NOT z[22]::BOOLEAN AS x_scr_dp, pt.pgn AS pgn, IFF(s_uac AND s_dp, zc[17]::NUMBER / pt.pgn, NULL) AS fuc, IFF(s_uac AND s_dp AND s_ua AND zc[17]::NUMBER > 0, zc[14]::NUMBER / pt.pgn, NULL) AS fux, IFF(s_sp AND s_dp, zc[24]::NUMBER / pt.pgn, NULL) AS fsc, IFF(s_sp AND s_dp AND zc[24]::NUMBER > 0, zc[22]::NUMBER / pt.pgn, NULL) AS fsx, IFF(s.hw_gl AND s_sp AND s_gl, zc[23]::NUMBER / pt.pgn, NULL) AS fsg, IFF(s.sp_ok AND z[21]::BOOLEAN, zc[20]::NUMBER / pt.pgn, NULL) AS fsp, (fuc > 0 AND (fuc < 1e-12 OR COALESCE(fux < 1e-12, FALSE))) AS r_ua_dp, (fsc > 0 AND (fsc < IFF(s.pg = 'Mobile', 1e-4, 1e-12) OR COALESCE(fsx < 1e-12, FALSE))) AS r_scr_dp, (fsg > 0 AND fsg < 1e-12) AS r_scr_gl, (fsp > 0 AND fsp < IFF(s.pg = 'Mobile', 1e-4, 1e-12)) AS r_scr_pg FROM st s JOIN seen USING (h) LEFT JOIN best b ON b.h = s.h LEFT JOIN omx o ON o.osf = s.osf LEFT JOIN pgt pt ON pt.pg = s.pg ), t AS ( SELECT c.*, IFF(f_ua_dp,1,0)+IFF(f_scr_dp,1,0)+IFF(f_scr_gl,1,0)+IFF(f_scr_os,1,0)+IFF(f_osv,1,0)+IFF(f_dp_new,1,0) AS n0, IFF(mobile, n0 >= 1, n0 >= 2 OR (n0 >= 1 AND (w_scr0 OR f_dp_new))) AS t0, IFF(t0 AND NOT no_score,'D',sb) AS band_v1, IFF(g_ua_dp,1,0)+IFF(h_scr_dp,1,0)+IFF(h_scr_gl,1,0)+IFF(h_scr_pg,1,0)+IFF(p_dp_new AND mob2,1,0) AS nfail, IFF(x_ua_dp,1,0)+IFF(x_scr_dp,1,0) AS nxw, IFF(mob2, nxw, nxw + IFF(h_w_scr,1,0) + IFF(p_dp_new,1,0)) AS nwarn, IFF(mob2, nfail >= 1, nfail >= 2 OR (nfail >= 1 AND nwarn >= 1)) AS t3, IFF(t3 AND NOT no_score,'D',sb3) AS band, IFF(r_ua_dp,1,0)+IFF(r_scr_dp,1,0)+IFF(r_scr_gl,1,0)+IFF(r_scr_pg,1,0) AS nrare, IFF(mob2, nrare, nrare + IFF(h_w_scr,1,0) + IFF(p_dp_new,1,0)) AS nwarn4, IFF(mob2, nfail >= 1, nfail >= 2 OR (nfail >= 1 AND nwarn4 >= 1)) AS t4v, IFF(t4v AND NOT no_score,'D',sb3) AS band4, t4v OR (NOT mob2 AND g_ua_dp) AS ta, t4v OR (NOT mob2 AND nwarn4 >= 2) AS tb, nfail - IFF(h_scr_gl AND NOT mob2,1,0) AS nfail_c, nwarn4 + IFF(h_scr_gl AND NOT mob2,1,0) AS nwarn_c, IFF(mob2, nfail >= 1, nfail_c >= 2 OR (nfail_c >= 1 AND nwarn_c >= 1)) AS tc, IFF(mob2, nfail >= 1, nfail_c >= 2 OR (nfail_c >= 1 AND nwarn_c >= 1) OR g_ua_dp OR nwarn_c >= 2) AS tabc, IFF(ta AND NOT no_score,'D',sb3) AS band_a, IFF(tb AND NOT no_score,'D',sb3) AS band_b, IFF(tc AND NOT no_score,'D',sb3) AS band_c, IFF(tabc AND NOT no_score,'D',sb3) AS band_abc FROM c ) , g AS (SELECT r.session, r.d, r.risk, r.verified, r.ch, r.solved, t.*, IFF(t.pg='Mobile','mob','desk') AS md2, IFF(t.mobile,'mob','desk') AS md1, (r.d = 15 AND band_v1 = 'D' AND f_ua_dp AND f_scr_dp AND NOT f_scr_gl AND NOT f_scr_os AND NOT f_osv AND NOT f_dp_new AND NOT w_scr0) AS d15g, CASE WHEN r.d = 63 THEN 1 WHEN r.d IN (31,15) THEN 2 WHEN r.d = 7 THEN 3 ELSE 4 END AS agr, ARRAY_TO_STRING(ARRAY_CONSTRUCT_COMPACT(IFF(g_ua_dp,'UAxDP',NULL), IFF(h_scr_dp,'SCRxDP',NULL), IFF(h_scr_gl,'SCRxGL',NULL), IFF(h_scr_pg,'SCRxPG',NULL), IFF(p_dp_new AND mob2,'DPnew',NULL)), ' ') AS fails3, ARRAY_TO_STRING(ARRAY_CONSTRUCT_COMPACT(IFF(h_w_scr,'SCRnew',NULL), IFF(p_dp_new AND NOT mob2,'DPnew',NULL), IFF(r_ua_dp,'UAxDPr',NULL), IFF(r_scr_dp,'SCRxDPr',NULL), IFF(r_scr_gl,'SCRxGLr',NULL), IFF(r_scr_pg,'SCRxPGr',NULL)), ' ') AS warns4, IFF((fuc > 0 AND (fuc < 1e-4 OR COALESCE(fux < 1e-4, FALSE))),1,0)+IFF((fsc > 0 AND (fsc < 1e-4 OR COALESCE(fsx < 1e-4, FALSE))),1,0)+IFF((fsg > 0 AND (fsg < 1e-4)),1,0)+IFF((fsp > 0 AND (fsp < 1e-4)),1,0) AS nrU4, IFF(mob2, nfail >= 1, nfail >= 2 OR (nfail >= 1 AND nrU4 + IFF(mob2, 0, IFF(h_w_scr,1,0) + IFF(p_dp_new,1,0)) >= 1)) AS tU4, IFF(tU4 AND NOT no_score,'D',sb3) AS bandU4, IFF((fuc > 0 AND (fuc < 1e-3 OR COALESCE(fux < 1e-3, FALSE))),1,0)+IFF((fsc > 0 AND (fsc < 1e-3 OR COALESCE(fsx < 1e-3, FALSE))),1,0)+IFF((fsg > 0 AND (fsg < 1e-3)),1,0)+IFF((fsp > 0 AND (fsp < 1e-3)),1,0) AS nrU3, IFF(mob2, nfail >= 1, nfail >= 2 OR (nfail >= 1 AND nrU3 + IFF(mob2, 0, IFF(h_w_scr,1,0) + IFF(p_dp_new,1,0)) >= 1)) AS tU3, IFF(tU3 AND NOT no_score,'D',sb3) AS bandU3 FROM sess_raw r JOIN t ON t.h = r.h) , v AS (SELECT g.session, g.d, g.risk, g.d15g, g.agr, g.no_score, x.value:v::STRING AS ver, x.value:b::STRING AS bd, x.value:t::BOOLEAN AS tr, x.value:m::STRING AS m, DECODE(x.value:b::STRING,'A',1,'B',2,'C',3,'D',4,9) AS rk FROM g, LATERAL FLATTEN(ARRAY_CONSTRUCT(OBJECT_CONSTRUCT('v','v1','b',band_v1,'t',t0,'m',md1), OBJECT_CONSTRUCT('v','v3','b',band,'t',t3,'m',md2), OBJECT_CONSTRUCT('v','v4','b',band4,'t',t4v,'m',md2), OBJECT_CONSTRUCT('v','v4a','b',band_a,'t',ta,'m',md2), OBJECT_CONSTRUCT('v','v4b','b',band_b,'t',tb,'m',md2), OBJECT_CONSTRUCT('v','v4c','b',band_c,'t',tc,'m',md2), OBJECT_CONSTRUCT('v','v4abc','b',band_abc,'t',tabc,'m',md2), OBJECT_CONSTRUCT('v','U1e-4','b',bandU4,'t',tU4,'m',md2), OBJECT_CONSTRUCT('v','U1e-3','b',bandU3,'t',tU3,'m',md2))) x) SELECT r FROM ( SELECT 'X4|'||d||'|'||band4||'|'||COUNT(*)||'|'||COUNT_IF(risk='High')||'|'||COUNT_IF(verified)||'|'||COUNT_IF(ch)||'|'||COUNT_IF(ch AND NOT COALESCE(solved,FALSE))||'|'||ROUND(AVG(score3),3) AS r FROM g GROUP BY d, band4 UNION ALL SELECT 'SH|'||ver||'|same='||COUNT_IF(rk=agr)||'|up='||COUNT_IF(rk<agr)||'|down='||COUNT_IF(rk>agr)||'|prom='||COUNT_IF(d IN (1,3) AND rk<=2)||'|dem='||COUNT_IF(d IN (63,31,15) AND rk=4)||'|D='||COUNT_IF(rk=4)||'|Dhigh='||COUNT_IF(rk=4 AND risk='High')||'|notD='||COUNT_IF(rk<>4)||'|notDhigh='||COUNT_IF(rk<>4 AND risk='High')||'|G1AB='||COUNT_IF(d IN (1,3) AND rk<=2)||'/'||COUNT_IF(d IN (1,3))||'|G5='||COUNT_IF(d=63 AND rk=1)||'/'||COUNT_IF(d=63)||'|m1D='||COUNT_IF(d=-1 AND rk=4)||'/'||COUNT_IF(d=-1) FROM v GROUP BY ver UNION ALL SELECT 'G3|'||ver||'|'||m||'|'||IFF(tr AND NOT no_score,'Dchk','pass')||'|'||COUNT(*)||'|'||COUNT_IF(risk='High') FROM v GROUP BY ver, m, IFF(tr AND NOT no_score,'Dchk','pass') UNION ALL SELECT 'D15|'||ver||'|'||bd||'|'||COUNT(*)||'|'||COUNT_IF(risk='High') FROM v WHERE d15g GROUP BY ver, bd UNION ALL SELECT 'FL|'||ver||'|intoD='||COUNT_IF(v.bd='D' AND g.band<>'D')||'/'||COUNT_IF(v.bd='D' AND g.band<>'D' AND g.risk='High')||'|outD='||COUNT_IF(v.bd<>'D' AND g.band='D')||'/'||COUNT_IF(v.bd<>'D' AND g.band='D' AND g.risk='High') FROM v JOIN g ON g.session=v.session GROUP BY ver UNION ALL SELECT 'WF4|'||md2||'|f'||LEAST(nfail,2)||'|w'||LEAST(nwarn4,3)||'|'||COUNT(*)||'|'||COUNT_IF(risk='High') FROM g WHERE NOT no_score GROUP BY md2, LEAST(nfail,2), LEAST(nwarn4,3) UNION ALL SELECT 'RARE|v4|'||md2||'|'||IFF(r_ua_dp,'UAxDPr ','')||IFF(r_scr_dp,'SCRxDPr ','')||IFF(r_scr_gl,'SCRxGLr ','')||IFF(r_scr_pg,'SCRxPGr','')||'|'||COUNT(*)||'|'||COUNT_IF(risk='High') FROM g WHERE nrare>0 GROUP BY md2, r_ua_dp, r_scr_dp, r_scr_gl, r_scr_pg UNION ALL SELECT 'RARE|U1e-4|'||md2||'|nrare='||LEAST(nrU4,3)||'|'||COUNT(*)||'|'||COUNT_IF(risk='High') FROM g GROUP BY md2, LEAST(nrU4,3) UNION ALL SELECT 'RARE|U1e-3|'||md2||'|nrare='||LEAST(nrU3,3)||'|'||COUNT(*)||'|'||COUNT_IF(risk='High') FROM g GROUP BY md2, LEAST(nrU3,3) UNION ALL SELECT 'G4|'||IFF(NOT g_ua_dp AND NOT r_ua_dp,'UAxDP ok','UAxDP fail/rare')||'|'||COUNT(*)||'|'||COUNT_IF(risk='High') FROM g WHERE mob2 AND NOT s_sp AND NOT no_score GROUP BY IFF(NOT g_ua_dp AND NOT r_ua_dp,'UAxDP ok','UAxDP fail/rare') UNION ALL SELECT 'G4|mobile all|'||COUNT(*)||'|'||COUNT_IF(risk='High') FROM g WHERE mob2 ) WHERE r < 'S' ORDER BY r$$